'use strict';
const ContentSchema=window.EvervaleContentSchema;
const typeLabel=kind=>ContentSchema.types.find(x=>x.key===kind)?.label||kind;
const groupLabels={basic:'ข้อมูลพื้นฐาน',combat:'การต่อสู้',attributes:'ค่าสถานะ',special:'ความสามารถพิเศษ',economy:'ราคาและเศรษฐกิจ',equipment:'อุปกรณ์',skills:'สกิลและความชำนาญ',world:'โลกและสถานที่',narrative:'เรื่องราว',recruitment:'การเข้าร่วม',element:'ธาตุ',behavior:'พฤติกรรม',effects:'ผลและความสามารถ',requirement:'เงื่อนไข',progression:'ความก้าวหน้า',effect:'เอฟเฟกต์',recipe:'สูตรปรุง'};
let editingContentKey=null,editorDraft=null,contentPage=0;const PAGE_SIZE=24;
function baseContentRows(){const previous=DB.overrides;try{DB.overrides={};return R.records(DB);}finally{DB.overrides=previous;}}
function fieldDefault(f){if(f.type==='number')return 0;if(f.type==='boolean')return false;if(['reference','tags','keyvalue','proficiencyPicker','lootPicker'].includes(f.type))return [];if(f.type==='select')return f.options?.[0]??'';return '';}
function assertJSONSafe(value,depth=0){if(depth>15)throw Error('ข้อมูลซ้อนลึกเกินไป');if(typeof value==='number'&&!Number.isFinite(value))throw Error('ตัวเลขไม่ถูกต้อง');if(Array.isArray(value)){if(value.length>10000)throw Error('รายการยาวเกินไป');value.forEach(x=>assertJSONSafe(x,depth+1));}else if(value&&typeof value==='object'){for(const [key,v] of Object.entries(value)){if(['__proto__','constructor','prototype'].includes(key))throw Error('ชื่อช่องไม่อนุญาต');assertJSONSafe(v,depth+1);}}}
function validateContentEdits(input){if(!input||typeof input!=='object'||Array.isArray(input)||JSON.stringify(input).length>2000000)throw Error('ข้อมูลต้องเป็น object และไม่เกิน 2 MB');assertJSONSafe(input);const bases=new Map(baseContentRows().map(x=>[x.key,x])),clean={};for(const [key,patch] of Object.entries(input)){if(key===window.EverTaleBattleData?.KEY){clean[key]=window.EverTaleBattleData.validate(patch);continue;}if(key===window.EvervaleMapData.KEY){clean[key]=window.EvervaleMapData.validate(patch);continue;}const base=bases.get(key);if(!base||!patch||typeof patch!=='object'||Array.isArray(patch))throw Error('ไม่พบรายการอ้างอิง '+key);const fields=new Map((ContentSchema.schemas[base.kind]?.fields||[]).map(f=>[f.key,f]));const out={};for(const [field,value] of Object.entries(patch)){if(['id','key','kind','name'].includes(field))continue;const f=fields.get(field);if(field==='displayName'){if(typeof value!=='string'||!value.trim()||value.length>150)throw Error('ชื่อที่แสดงต้องมี 1–150 ตัว');}else if(field==='enabled'){if(typeof value!=='boolean')throw Error('เปิดใช้งานต้องเป็น boolean');}else if(f){if(f.type==='number'){if(typeof value!=='number'||!Number.isFinite(value))throw Error(f.label+' ต้องเป็นตัวเลข');}else if(f.type==='boolean'){if(typeof value!=='boolean')throw Error(f.label+' ต้องเป็น boolean');}else if(['tags','reference','lootPicker'].includes(f.type)){if(!Array.isArray(value)||value.some(x=>typeof x!=='string'))throw Error(f.label+' ต้องเป็นรายการข้อความ');}else if(f.type==='keyvalue'){if(!Array.isArray(value)||value.some(x=>!x||typeof x.key!=='string'||typeof x.value!=='string'))throw Error(f.label+' ต้องเป็นรายการ key/value');}else if(f.type==='proficiencyPicker'){if(!Array.isArray(value)||value.some(x=>!x||typeof x.name!=='string'||typeof x.grade!=='string'))throw Error(f.label+' ต้องเป็นรายการ name/grade');}else if(typeof value!=='string')throw Error(f.label+' ต้องเป็นข้อความ');if(f.type==='image'&&value&&!/^(https?:\/\/|data:image\/(png|jpeg|webp|gif);base64,)/i.test(value))throw Error('รูปภาพต้องเป็น URL http/https หรือรูปที่อัปโหลด');}else if(!(field in base)&&!['description','levelRequirement'].includes(field))throw Error('ไม่รองรับช่อง '+field);else if(base[field]!==undefined&&base[field]!==null&&(Array.isArray(base[field])?!Array.isArray(value):typeof value!==typeof base[field]))throw Error('ชนิดข้อมูล '+field+' ไม่ถูกต้อง');if(field==='levelRequirement'&&(!Number.isInteger(value)||value<0||value>1000))throw Error('เลเวลต้องเป็นจำนวนเต็ม 0–1000');out[field]=value;}clean[key]=out;}return clean;}
function persistContentEdits(next){const clean=validateContentEdits(next);localStorage.setItem('evervale-content:'+uid,JSON.stringify(clean));DB.overrides=clean;window.EvervaleMaps?.libraryUpdated();window.EverTaleBattle?.libraryUpdated();window.EvervaleSave?.cacheContent?.(clean);window.dispatchEvent(new Event('evervale-content-save'));}
function fieldHelp(kind,key){const help=ContentSchema.help?.[kind]?.[key];if(!help)return '';const parts=typeof help==='string'?help:Object.entries(help).map(([k,v])=>k+': '+v).join('\n');return `<details class="field-help"><summary>คำอธิบายจากเกมเก่า</summary><p>${escapeHTML(parts)}</p></details>`;}
function fieldSummary(field,value){if(value===undefined||value===null||value==='')return '—';if(field.type==='boolean')return value?'ใช่':'ไม่ใช่';if(['reference','lootPicker'].includes(field.type)){const refs=R.records(DB);return (Array.isArray(value)?value:[]).map(v=>{const row=refs.find(x=>x.id===v||x.name===v);return row?.displayName||row?.name||v;}).join(', ')||'—';}if(Array.isArray(value))return value.map(x=>typeof x==='object'?(x.name?x.name+' · '+x.grade:x.key+': '+x.value):x).join(', ')||'—';return String(value);}
function sourceDetails(row){return `<details class="record-details"><summary>ดูข้อมูลครบทุกช่อง (${ContentSchema.schemas[row.kind].fields.length} ช่อง)</summary><dl>${ContentSchema.schemas[row.kind].fields.map(f=>`<dt>${escapeHTML(f.label)}</dt><dd>${escapeHTML(fieldSummary(f,f.key==='name'?(row.displayName||row.name):row[f.key]))}</dd>`).join('')}</dl></details>`;}
function renderFullDatabase(){const full=returnScreen==='menuScreen',query=$('dbSearch').value.trim().toLowerCase(),kind=$('dbKind').value,rows=R.records(DB);const available=full?rows:rows.filter(x=>x.key in s.known);const visible=available.filter(x=>(kind==='all'||x.kind===kind)&&[x.name,x.displayName,x.description].some(v=>String(v||'').toLowerCase().includes(query)));contentPage=Math.min(contentPage,Math.max(0,Math.ceil(visible.length/PAGE_SIZE)-1));$('dbCount').textContent=(full?'ฐานข้อมูลทั้งหมด '+rows.length+' รายการ':'ค้นพบแล้ว '+available.length+' รายการ')+' • พบตามตัวกรอง '+visible.length+' รายการ';const pageRows=visible.slice(contentPage*PAGE_SIZE,(contentPage+1)*PAGE_SIZE);$('dbList').innerHTML=pageRows.length?pageRows.map(row=>{const depth=full?2:Math.max(s.known[row.key]||0,R.has(s,'Appraisal Eye',DB)?2:R.has(s,'Appraisal',DB)?1:0),reason=R.learnStatus(s,row,DB),learned=s.learned.includes(row.key);return `<article><span class="tag">${escapeHTML(typeLabel(row.kind))}</span><span class="tag">${full?(row.enabled===false?'ปิดใช้งาน':DB.overrides?.[row.key]?'แก้ไขแล้ว':'ข้อมูลต้นฉบับ'):learned?'เรียนแล้ว':'ค้นพบแล้ว'}</span><h2>${escapeHTML(row.displayName||row.name)}</h2><p>${depth>=1?escapeHTML(row.description||row.passive||row.passiveEffects||'ไม่มีคำอธิบายเพิ่มเติม'):'คุณสมบัติ: ยังไม่ทราบ'}</p>${depth>=2?sourceDetails(row):'<p class="muted">รายละเอียดและเงื่อนไข: ยังไม่ทราบ</p>'}${full?`<p class="record-support">${['skill','spell','proficiency'].includes(row.kind)?'ข้อมูลต้นฉบับครบ • ใช้ได้เฉพาะกลไกที่เชื่อมกับเกมปัจจุบันแล้ว':'ข้อมูลและฟอร์มพร้อมแก้ไข • ระบบของหมวดนี้ยังรอเชื่อมเข้าเกม'}</p><button data-edit="${escapeHTML(row.key)}">แก้ไขรายการ</button>`:(!s.dead&&!s.event&&depth<2?`<button data-research="${escapeHTML(row.key)}" ${s.gold<10||!s.character?'disabled':''}>ถามอาจารย์ / ศึกษา · 10 เหรียญ 2 ชม.</button>`:'')+(['skill','spell'].includes(row.kind)?`<button data-learn="${escapeHTML(row.key)}" ${reason||s.dead||s.event?'disabled':''}>${escapeHTML(reason||'เรียนวิชานี้ · 20 เหรียญ 2 ชม.')}</button>`:'')}</article>`;}).join(''):'<article><h2>ไม่พบรายการ</h2><p>ลองเปลี่ยนหมวดหรือคำค้น</p></article>';
$('dbPagination').innerHTML=`<button id="dbPrev" ${contentPage===0?'disabled':''}>ก่อนหน้า</button><span>หน้า ${contentPage+1} / ${Math.max(1,Math.ceil(visible.length/PAGE_SIZE))}</span><button id="dbNext" ${(contentPage+1)*PAGE_SIZE>=visible.length?'disabled':''}>ถัดไป</button>`;$('dbPrev').onclick=()=>{contentPage--;renderFullDatabase();$('dbCount').scrollIntoView();};$('dbNext').onclick=()=>{contentPage++;renderFullDatabase();$('dbCount').scrollIntoView();};document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openContentEditor(b.dataset.edit));document.querySelectorAll('[data-research]').forEach(b=>b.onclick=()=>{if(!s.character||s.dead||s.event||s.gold<10)return;s.gold-=10;R.clock(s,120);s.turn++;R.discover(s,b.dataset.research,2);R.log(s,'ศึกษาข้อมูลจากอาจารย์และตำรา');save();renderFullDatabase();});document.querySelectorAll('[data-learn]').forEach(b=>b.onclick=()=>{try{R.learn(s,rows.find(x=>x.key===b.dataset.learn),DB);R.log(s,'เรียนรู้วิชาใหม่');save();renderFullDatabase();}catch(e){status(e.message);}});}
function makePairControl(field,value){const wrap=document.createElement('div');wrap.className='pair-control';const list=document.createElement('div'),add=document.createElement('button');add.type='button';add.textContent='เพิ่มแถว';const proficiency=field.type==='proficiencyPicker';function row(pair={}){const line=document.createElement('div');line.className='pair-row';const key=document.createElement('input');key.type='text';key.placeholder=proficiency?'ชื่อความชำนาญ':'ชื่อ / key';key.value=proficiency?pair.name||'':pair.key||'';if(proficiency)key.setAttribute('list','proficiencyNames');const val=proficiency?document.createElement('select'):document.createElement('input');if(proficiency){for(const grade of [...new Set(['D','C','B','A','S',pair.grade].filter(Boolean))])val.add(new Option(grade,grade));val.value=pair.grade||'D';}else{val.type='text';val.placeholder='ค่า / value';val.value=pair.value||'';}const remove=document.createElement('button');remove.type='button';remove.textContent='ลบแถว';remove.onclick=()=>line.remove();line.append(key,val,remove);list.append(line);}for(const pair of Array.isArray(value)?value:[])row(pair);add.onclick=()=>row();wrap.append(list,add);wrap.getValue=()=>Array.from(list.children).filter(line=>line.children[0].value.trim()).map(line=>proficiency?{name:line.children[0].value.trim(),grade:line.children[1].value}:{key:line.children[0].value.trim(),value:line.children[1].value});return wrap;}
function makeReferenceControl(field,value){const wrap=document.createElement('div');wrap.className='reference-control';const chosen=new Set(Array.isArray(value)?value:[]),filter=document.createElement('input'),list=document.createElement('div');filter.type='search';filter.placeholder='ค้นหาเพื่อเลือก '+(field.refType?typeLabel(field.refType):'ของดรอป');list.className='reference-options';const allowed=field.type==='lootPicker'?['item','dropItem','weapon','armor','helmet','boots','accessory']:[field.refType];const options=R.records(DB).filter(x=>allowed.includes(x.kind)).map(x=>({value:field.byName||field.type==='lootPicker'?x.name:x.id,label:(x.displayName||x.name)+' · '+typeLabel(x.kind)}));for(const v of chosen)if(!options.some(x=>x.value===v))options.push({value:v,label:v+' (อ้างอิงเดิม)'});for(const entry of options){const label=document.createElement('label');label.className='reference-option';const checkbox=document.createElement('input');checkbox.type='checkbox';checkbox.value=entry.value;checkbox.checked=chosen.has(entry.value);checkbox.onchange=()=>checkbox.checked?chosen.add(entry.value):chosen.delete(entry.value);label.append(checkbox,document.createTextNode(entry.label));label.dataset.search=entry.label.toLowerCase();list.append(label);}const count=document.createElement('small');const update=()=>count.textContent='เลือกแล้ว '+chosen.size+' รายการ';list.addEventListener('change',update);filter.oninput=()=>{for(const el of list.children)el.hidden=!el.dataset.search.includes(filter.value.toLowerCase());};update();wrap.append(filter,count,list);wrap.getValue=()=>[...chosen];return wrap;}
function makeFieldControl(field,value){value=value??fieldDefault(field);let node;if(['keyvalue','proficiencyPicker'].includes(field.type))return makePairControl(field,value);if(['reference','lootPicker'].includes(field.type))return makeReferenceControl(field,value);if(field.type==='textarea'){node=document.createElement('textarea');node.rows=4;node.value=value;}else if(field.type==='select'){node=document.createElement('select');for(const opt of [...new Set([...(field.options||[]),value])])node.add(new Option(opt||'—',opt));node.value=value;}else if(field.type==='boolean'){node=document.createElement('input');node.type='checkbox';node.checked=!!value;}else if(field.type==='image'){const wrap=document.createElement('div'),url=document.createElement('input'),file=document.createElement('input'),preview=document.createElement('img');url.type='text';url.placeholder='URL รูปภาพ หรืออัปโหลดจากเครื่อง';url.value=value;file.type='file';file.accept='image/png,image/jpeg,image/webp,image/gif';preview.alt='ภาพตัวอย่าง';preview.className='editor-image';function update(){const okay=/^(https?:\/\/|data:image\/(png|jpeg|webp|gif);base64,)/i.test(url.value);preview.hidden=!okay;if(okay)preview.src=url.value;else preview.removeAttribute('src');}url.oninput=update;file.onchange=()=>{const f=file.files[0];if(!f)return;if(f.size>600000){$('dbEditStatus').textContent='รูปภาพต้องไม่เกิน 600 KB';return;}if(!/^image\/(png|jpeg|webp|gif)$/.test(f.type)){ $('dbEditStatus').textContent='รองรับ PNG JPEG WebP GIF';return;}const reader=new FileReader();reader.onload=()=>{url.value=reader.result;update();};reader.readAsDataURL(f);};update();wrap.append(url,file,preview);wrap.getValue=()=>url.value.trim();return wrap;}else{node=document.createElement('input');node.type=field.type==='number'?'number':'text';if(field.type==='number')node.step='any';node.value=field.type==='tags'?(Array.isArray(value)?value.join(', '):''):value;}node.getValue=()=>field.type==='number'?(node.value===''?0:Number(node.value)):field.type==='boolean'?node.checked:field.type==='tags'?node.value.split(',').map(x=>x.trim()).filter(Boolean):node.value;return node;}
function renderEditorFields(){const schema=ContentSchema.schemas[editorDraft.kind];$('dbSchemaFields').replaceChildren();const groups=new Map();for(const field of schema.fields){const group=field.group||'basic';if(!groups.has(group)){const box=document.createElement('fieldset'),legend=document.createElement('legend');legend.textContent=groupLabels[group]||group;box.append(legend);groups.set(group,box);$('dbSchemaFields').append(box);}const holder=document.createElement('div');holder.className='schema-field';holder.dataset.field=field.key;const label=document.createElement('label');label.textContent=field.label+(field.required?' *':'');const value=field.key==='name'?(editorDraft.displayName||editorDraft.name):editorDraft[field.key];const control=makeFieldControl(field,value);control.dataset.control=field.key;control.id='field-'+field.key;label.htmlFor=control.id;if(field.required&&['INPUT','TEXTAREA','SELECT'].includes(control.tagName))control.required=true;holder.append(label,control);if(field.type==='tags'){const hint=document.createElement('small');hint.textContent='คั่นแต่ละค่าด้วยจุลภาค (,)';holder.append(hint);}if(field.key==='name'){const hint=document.createElement('small');hint.textContent='ชื่ออ้างอิงต้นฉบับ: '+editorDraft.name+' • เปลี่ยนชื่อที่แสดงได้โดยไม่ทำให้รายการอ้างอิงเดิมหาย';holder.append(hint);}if(ContentSchema.help?.[editorDraft.kind]?.[field.key])holder.insertAdjacentHTML('beforeend',fieldHelp(editorDraft.kind,field.key));groups.get(group).append(holder);}$('dbEditEnabled').checked=editorDraft.enabled!==false;$('dbEditJson').value=JSON.stringify(editorDraft,null,2);}
function openContentEditor(key){if(!uid||returnScreen!=='menuScreen')return;const row=R.records(DB).find(x=>x.key===key);if(!row)return;editingContentKey=key;editorDraft=JSON.parse(JSON.stringify(row));$('dbEditHeading').textContent='แก้ไข'+typeLabel(row.kind)+' • '+ContentSchema.schemas[row.kind].fields.length+' ช่อง';$('dbEditIdentity').textContent=row.name+' · '+row.id;$('dbEditStatus').textContent='';renderEditorFields();$('dbDialog').showModal();$('dbDialog').scrollTop=0;}
$('dbEditCancel').onclick=()=>$('dbDialog').close();
$('dbEditForm').onsubmit=e=>{e.preventDefault();try{const next={...editorDraft};for(const field of ContentSchema.schemas[editorDraft.kind].fields){const value=$('field-'+field.key).getValue();if(field.required&&(value===''||value===null||Array.isArray(value)&&!value.length))throw Error('ต้องกรอก '+field.label);if(field.key==='name')next.displayName=value.trim();else next[field.key]=value;}next.enabled=$('dbEditEnabled').checked;for(const field of ['id','key','kind','name'])delete next[field];persistContentEdits({...DB.overrides,[editingContentKey]:next});$('dbDialog').close();renderFullDatabase();status('บันทึกข้อมูลทุกช่องแล้ว');}catch(err){$('dbEditStatus').textContent='บันทึกไม่ได้: '+err.message;}};
$('dbApplyJson').onclick=()=>{try{const parsed=JSON.parse($('dbEditJson').value);if(!parsed||typeof parsed!=='object'||Array.isArray(parsed))throw Error('ต้องเป็น JSON object');const patch={...parsed};delete patch.id;delete patch.kind;delete patch.key;delete patch.name;validateContentEdits({[editingContentKey]:patch});editorDraft={...editorDraft,...patch};renderEditorFields();$('dbEditStatus').textContent='นำ JSON เข้าฟอร์มแล้ว • กดบันทึกการแก้ไขเพื่อยืนยัน';}catch(err){$('dbEditStatus').textContent='นำ JSON ไม่ได้: '+err.message;}};
$('dbEditReset').onclick=()=>{if(!confirm('คืนค่ารายการนี้เป็นข้อมูลเดิมทุกช่อง?'))return;try{const next={...DB.overrides};delete next[editingContentKey];persistContentEdits(next);$('dbDialog').close();renderFullDatabase();status('คืนค่ารายการเดิมแล้ว');}catch(err){$('dbEditStatus').textContent=err.message;}};
$('dbExport').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify({format:'evervale-content-v1',overrides:DB.overrides||{}},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='evertale-content-edits.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('dbImport').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>2000000)throw Error('ไฟล์ใหญ่เกิน 2 MB');const data=JSON.parse(await file.text());if(data.format!=='evervale-content-v1')throw Error('รูปแบบไฟล์ไม่รองรับ');const clean=validateContentEdits(data.overrides);if(!confirm('นำเข้าข้อมูลแก้ไข '+Object.keys(clean).length+' รายการแทนข้อมูลแก้ไขปัจจุบัน?'))return;persistContentEdits(clean);renderFullDatabase();status('นำเข้าข้อมูลแก้ไขแล้ว');}catch(err){status('นำเข้าไม่ได้: '+err.message);}finally{e.target.value='';}};
$('dbKind').innerHTML='<option value="all">ทั้งหมด</option>'+ContentSchema.types.map(t=>`<option value="${t.key}">${escapeHTML(t.label)}</option>`).join('');
const pagination=document.createElement('div');pagination.id='dbPagination';pagination.className='db-pagination';$('dbList').after(pagination);
const names=document.createElement('datalist');names.id='proficiencyNames';for(const row of R.records(DB).filter(x=>x.kind==='proficiency'))names.append(new Option(row.name,row.name));document.body.append(names);
$('dbSearch').oninput=$('dbKind').onchange=()=>{contentPage=0;renderFullDatabase();};
window.EvervaleEditor={renderDatabase:renderFullDatabase,validate:validateContentEdits,snapshot:()=>JSON.parse(JSON.stringify(DB.overrides||{})),applyRemote(data){const clean=validateContentEdits(data);localStorage.setItem('evervale-content:'+uid,JSON.stringify(clean));DB.overrides=clean;window.EvervaleMaps?.libraryUpdated();window.EverTaleBattle?.libraryUpdated();window.EvervaleSave?.cacheContent?.(clean);if(screen==='databaseScreen')renderFullDatabase();},cloudStatus(text,conflict=false){$('contentCloudStatus').textContent=text;if($('mapCloudStatus'))$('mapCloudStatus').textContent=text;if($('battleCloudStatus'))$('battleCloudStatus').textContent=text;$('contentPull').hidden=$('contentPush').hidden=!conflict;}};
